pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin = address(0xA11CE);
    address manager = address(0xB0B);

    function setUp() public {
        c = new C();
        MockConfig cfg = new MockConfig();
        c.initialize(address(cfg));
    }

    function testFuzz_property(bool doPause, address unusedActor) public {
        // Pause via a manager (MockConfig grants MANAGER role to everyone).
        vm.prank(manager);
        c.pause();

        if (!doPause) {
            // Unpause via an admin (MockConfig grants DEFAULT_ADMIN to everyone).
            vm.prank(admin);
            c.unpause();
        }

        // General rule: after pause() only, paused() is true; after pause()+unpause(), paused() is false.
        assertTrue(c.paused() == doPause);
    }
}

