contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address configAddr, uint256 seed) public {
        vm.assume(configAddr != address(0));
        // keep the fuzzed domain wide; seed just widens the input space
        c.initialize(configAddr);
        bool ok = true;
        try c.paused() returns (bool p) {
            ok = !p;
        } catch {
            ok = false;
        }
        // General rule: for any admissible setup, a freshly initialized LRTDepositPool
        // reports its pause state via paused(), which must start unpauseD (false).
        assertTrue(ok);
    }
}

