pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 seed) public {
        vm.assume(actor != address(0));
        // The constructor of C disables initializers, so spawn a fresh copy of the
        // SAME runtime code (still P vs M code) whose storage is untouched and can
        // be initialized.
        CloneFactory factory = new CloneFactory();
        C cloned = C(factory.spawn(address(c)));

        // Permissive config: any caller holds every role.
        cloned.initialize(address(new PermissiveConfig()));

        // First pause succeeds for any caller (contract is unpaused in both P and M).
        vm.prank(actor);
        cloned.pause();

        // GENERAL RULE: a paused contract is paused — a second pause() must revert.
        vm.prank(actor);
        bool ok;
        try cloned.pause() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "pause must not be repeatable while paused");
    }
}

contract CloneFactory {
    // Deploys the runtime code of `impl` as a fresh contract (empty storage).
    function spawn(address impl) external returns (address out) {
        assembly {
            let size := extcodesize(impl)
            let ptr := mload(0x40)
            extcodecopy(impl, ptr, 0, size)
            out := create(0, ptr, size)
        }
    }
}

contract PermissiveConfig {
    function hasRole(bytes32, address) external pure returns (bool) { return true; }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function rsETH() external pure returns (address) { return address(this); }
    function getContract(bytes32) external pure returns (address) { return address(this); }
    function getAssetPrice(address) external pure returns (uint256) { return 1; }
    function getRSETHPrice() external pure returns (uint256) { return 1; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        // C's constructor disables its own initializers, so we deploy it behind a
        // minimal delegatecall proxy: initialize() then runs in the proxy's storage
        // and can set lrtConfig. The executed code (including paused()) is still C's.
        C impl = new C();
        Proxy p = new Proxy(address(impl));
        c = C(address(p));
        MockConfig cfg = new MockConfig();
        c.initialize(address(cfg));
    }

    function testFuzz_property(address manager, address admin, uint256 seed) public {
        vm.assume(manager != address(0) && admin != address(0));

        // The manager (MockConfig grants every role to everyone) pauses c.
        vm.prank(manager);
        c.pause();

        // General rule: once a successful pause has occurred, an admin unpause()
        // must succeed, because the real stored pause state is true.
        vm.prank(admin);
        bool ok;
        try c.unpause() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "unpause after a successful pause must succeed");
    }
}

contract Proxy {
    address public implementation;

    constructor(address impl) {
        implementation = impl;
    }

    fallback() external payable {
        address target = implementation;
        assembly {
            calldatacopy(0, 0, calldatasize())
            let r := delegatecall(gas(), target, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch r
            case 0 {
                revert(0, returndatasize())
            }
            default {
                return(0, returndatasize())
            }
        }
    }
}

contract MockConfig {
    function hasRole(bytes32, address) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address manager) public {
        vm.assume(manager != address(0));

        // Attempt to pause the contract from an arbitrary (fuzzed) caller.
        vm.prank(manager);
        bool pauseOk;
        try c.pause() {
            pauseOk = true;
        } catch {
            pauseOk = false;
        }

        // GENERAL RULE: if a pause attempt succeeds, the contract's public
        // paused() view must report true afterwards (the pause state is
        // genuinely stored). The buggy paused() always returns false, so any
        // successful pause breaks this; the reference always obeys it.
        assertTrue(!pauseOk || c.paused(), "successful pause must be reported by paused()");
    }
}
